<?php
/** @noinspection PhpUnhandledExceptionInspection */
declare(strict_types=1);

// Test generated by Claude Code.

namespace Tests\User\Support;

use Module\User\Model\User;
use Module\User\Model\UserRepository;
use Module\User\Support\TokenService;
use PHPUnit\Framework\Attributes\DataProvider;
use PHPUnit\Framework\Attributes\Test;
use Symfony\Component\Security\Core\Exception\BadCredentialsException;
use Tests\IntegrationTestCase;

class TokenServiceTest extends IntegrationTestCase
{
    private const int USER_ID = 50;
    private const string USER_TOKEN = '50-validtokenhex';
    private const string USER_EMAIL = 'user@example.com';

    private TokenService $sut;

    private UserRepository $userRepository;

    public function setUp(): void
    {
        parent::setUp();

        $this->userRepository = $this->container->get(UserRepository::class);

        $this->sut = new TokenService($this->userRepository);
        $this->prepareDb();
    }

    #[Test]
    public function generateTokenReturnsUserIdPrefixedToken(): void
    {
        $token = $this->sut->generateToken(self::USER_ID);

        $this->assertStringStartsWith(self::USER_ID . '-', $token);
        $this->assertSame(2, count(explode('-', $token)));
    }

    #[Test, DataProvider('dataProviderValidateToken')]
    public function validateToken(
        string $token,
        ?string $expectedEmail,
        string $expectedExceptionClass,
        string $expectedExceptionMessage,
    ): void {
        if ($expectedExceptionClass) {
            $this->expectException($expectedExceptionClass);
            $this->expectExceptionMessageMatches('/^' . preg_quote($expectedExceptionMessage, '/') . '$/');
        }

        $result = $this->sut->validateToken($token);

        $this->assertSame($expectedEmail, $result);
    }

    /**
     * @return array<string, array<string, mixed>>
     */
    public static function dataProviderValidateToken(): array
    {
        return [
            'invalid format - no hyphen' => [
                'token' => 'nohyphen',
                'expectedEmail' => null,
                'expectedExceptionClass' => BadCredentialsException::class,
                'expectedExceptionMessage' => 'Invalid token format.',
            ],
            'invalid format - multiple hyphens' => [
                'token' => '50-abc-def',
                'expectedEmail' => null,
                'expectedExceptionClass' => BadCredentialsException::class,
                'expectedExceptionMessage' => 'Invalid token format.',
            ],
            'user not found' => [
                'token' => '9999-validhex',
                'expectedEmail' => null,
                'expectedExceptionClass' => BadCredentialsException::class,
                'expectedExceptionMessage' => 'Invalid token.',
            ],
            'token mismatch' => [
                'token' => self::USER_ID . '-wrongtoken',
                'expectedEmail' => null,
                'expectedExceptionClass' => BadCredentialsException::class,
                'expectedExceptionMessage' => 'Invalid token.',
            ],
            'valid token returns email' => [
                'token' => self::USER_TOKEN,
                'expectedEmail' => self::USER_EMAIL,
                'expectedExceptionClass' => '',
                'expectedExceptionMessage' => '',
            ],
        ];
    }

    private function prepareDb(): void
    {
        $this->userRepository->saveWithId(
            User::factory(self::USER_EMAIL, 'Test User', 'hashed', ['ROLE_USER'], self::USER_TOKEN, self::USER_ID)
        );
        $this->userRepository->flush();
    }
}
